/*
 Problem: 4052. Cyclically Shift Rows and Columns
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 73.7 MB (18.47%)
 Tags: Array, Matrix, Simulation
*/
class Solution {
public:
    vector<vector<int>> cyclicShift(int n, vector<vector<int>>& grid, vector<int>& rowShift, vector<int>& colShift) {
        vector<vector<int>> res(n, vector<int>(n));

        for (int i = 0; i < n; ++i) {
            int k = rowShift[i] % n;
            for (int j = 0; j < n; ++j) {
                int nj = (j - k + n) % n;
                res[i][nj] = grid[i][j];
            }
        }

        vector<vector<int>> ans(n, vector<int>(n));

        for (int j = 0; j < n; ++j) {
            int k = colShift[j] % n;
            for (int i = 0; i < n; ++i) {
                int ni = (i - k + n) % n;
                ans[ni][j] = res[i][j];
            }
        }

        return ans;
    }
};
